def test_output_shape():
    img = [[1.0] * 5 for _ in range(5)]
    k = [[1.0] * 3 for _ in range(3)]
    out = solution.conv2d(img, k)
    assert len(out) == 3 and all(len(r) == 3 for r in out)
    assert out[0][0] == 9.0

def test_stride():
    img = [[1.0] * 5 for _ in range(5)]
    k = [[1.0] * 3 for _ in range(3)]
    assert solution.conv2d(img, k, stride=2) == [[9.0, 9.0], [9.0, 9.0]]

def test_padding():
    img = [[1.0] * 3 for _ in range(3)]
    k = [[1.0] * 3 for _ in range(3)]
    out = solution.conv2d(img, k, padding=1)
    assert out[0][0] == 4.0 and out[0][1] == 6.0 and out[1][1] == 9.0

def test_stride_and_padding():
    img = [[1.0] * 4 for _ in range(4)]
    k = [[1.0] * 3 for _ in range(3)]
    assert solution.conv2d(img, k, stride=2, padding=1) == [[4.0, 6.0], [6.0, 9.0]]

def test_invalid_stride():
